def preencher(apps, schema_editor):
    """Dia de trabalho a partir da entrada, tipos de pausa de origem e uma
    linha de histórico por cada correção já feita. O valor anterior a essas
    correções perdeu-se: ficam com previous_known a falso."""
    TimeEntry = apps.get_model("attendance", "TimeEntry")
    BreakType = apps.get_model("attendance", "BreakType")
    EntryCorrection = apps.get_model("attendance", "EntryCorrection")
    Restaurant = apps.get_model("core", "Restaurant")

    for entry in TimeEntry.objects.all().iterator():
        entry.work_date = django.utils.timezone.localtime(entry.check_in).date()
        entry.save(update_fields=["work_date"])
        if entry.corrected_by_id:
            EntryCorrection.objects.create(
                entry=entry,
                kind="ALTERAR",
                corrected_by_id=entry.corrected_by_id,
                reason=entry.correction_reason or "(sem motivo)",
                corrected_at=entry.corrected_at or entry.updated_at,
                new_check_in=entry.check_in,
                new_check_out=entry.check_out,
                previous_known=False,
            )

    for restaurant in Restaurant.objects.all():
        if not BreakType.objects.filter(restaurant=restaurant).exists():
            BreakType.objects.create(restaurant=restaurant, name="Refeição", paid=False)
            BreakType.objects.create(restaurant=restaurant, name="Pausa curta", paid=True)


